import{_ as i,C as r,o as l,c as p,j as n,a as t,E as a,a7 as s}from"./chunks/framework.C4ZIv4ii.js";const y=JSON.parse('{"title":"Off-Canvas Panels — slide-in drawers and popups in the Falcon Builder","description":"Design slide-in drawers and popups with the Falcon Builder, open them from any link or menu item or automatically, and switch them on and off on a schedule.","frontmatter":{"title":"Off-Canvas Panels — slide-in drawers and popups in the Falcon Builder","description":"Design slide-in drawers and popups with the Falcon Builder, open them from any link or menu item or automatically, and switch them on and off on a schedule."},"headers":[],"relativePath":"builder/off-canvas.md","filePath":"builder/off-canvas.md","lastUpdated":1795616640000}'),d={name:"builder/off-canvas.md"},h={id:"off-canvas-panels",tabindex:"-1"},g={id:"schedule",tabindex:"-1"};function c(u,e,f,m,v,b){const o=r("Badge");return l(),p("div",null,[n("h1",h,[e[0]||(e[0]=t("Off-Canvas Panels ",-1)),a(o,{type:"warning",text:"Pro"}),e[1]||(e[1]=t()),e[2]||(e[2]=n("a",{class:"header-anchor",href:"#off-canvas-panels","aria-label":'Permalink to "Off-Canvas Panels <Badge type="warning" text="Pro" />"'},"​",-1))]),e[6]||(e[6]=s('<p>An <strong>off-canvas panel</strong> is a slide-in drawer or popup that you design with the <a href="/falconcms/builder/overview.html">Falcon Builder</a>. Typical uses are a mobile menu, a cart sidebar or a newsletter popup. A panel opens from any link, button or menu item, or by itself when a page loads.</p><div class="info custom-block"><p class="custom-block-title">Pro</p><p>Creating and editing panels needs a <a href="/falconcms/guide/pro.html">Pro licence</a>. Panels made earlier keep working on the site without one.</p></div><h2 id="creating-a-panel" tabindex="-1">Creating a panel <a class="header-anchor" href="#creating-a-panel" aria-label="Permalink to &quot;Creating a panel&quot;">​</a></h2><ol><li>Go to <strong>Falcon Builder → Library</strong> and open the <strong>Off-Canvas</strong> tab.</li><li>Click <strong>New Off-Canvas</strong> and give the panel a name.</li><li>Design its content in the builder. <strong>Panel Options</strong> holds the panel&#39;s own settings.</li></ol><p>The Library can also duplicate, export, import and delete panels. Each panel has a switch that turns it off without deleting it.</p><h2 id="opening-and-closing-a-panel" tabindex="-1">Opening and closing a panel <a class="header-anchor" href="#opening-and-closing-a-panel" aria-label="Permalink to &quot;Opening and closing a panel&quot;">​</a></h2><p>Every panel has a <strong>trigger link</strong>, made from its name when you create it, for example <code>#offcanvas-mobile-menu</code>. The trigger link never changes, even if you rename the panel, so links to it keep working.</p><p>To open a panel, use any of these:</p><ul><li>a link, button or menu item whose URL is the trigger link</li><li><strong>Open Off-Canvas</strong> as a link&#39;s dynamic source in the builder</li><li>the <strong>Off-Canvas</strong> box under <strong>Appearance → Menus</strong>, which adds a menu item that opens a panel</li><li>an element with the attribute <code>data-falcon-offcanvas=&quot;mobile-menu&quot;</code> (the panel&#39;s slug)</li></ul><p>A link to <code>#offcanvas-close</code> closes the panel that is open. A button inside the panel is the usual place for it.</p><p>A page only loads the panels it links to, or that open on it by themselves. A panel nothing points at costs the page nothing.</p><h2 id="panel-options" tabindex="-1">Panel options <a class="header-anchor" href="#panel-options" aria-label="Permalink to &quot;Panel options&quot;">​</a></h2><h3 id="panel" tabindex="-1">Panel <a class="header-anchor" href="#panel" aria-label="Permalink to &quot;Panel&quot;">​</a></h3><ul><li><strong>Position</strong>: left, right, top, bottom or center. Position, size, corner radius and the close button&#39;s size can differ on tablet and mobile, so a drawer on the right on desktop can be a sheet at the bottom on a phone.</li><li><strong>Width</strong> in px, % or vw, and <strong>height</strong> in px or vh. A height of 0 fits the content.</li><li>Background color, corner radius and shadow.</li><li><strong>Animation</strong>: slide, fade, zoom or none, and its <strong>duration</strong>.</li></ul><h3 id="overlay" tabindex="-1">Overlay <a class="header-anchor" href="#overlay" aria-label="Permalink to &quot;Overlay&quot;">​</a></h3><p>The overlay is the shaded area behind the panel. You set its color, <strong>Overlay Opacity</strong> and <strong>Background Blur</strong>.</p><h3 id="closing" tabindex="-1">Closing <a class="header-anchor" href="#closing" aria-label="Permalink to &quot;Closing&quot;">​</a></h3><ul><li><strong>Close on Overlay Click</strong></li><li><strong>Close with Esc Key</strong></li><li>a close button, with its color and size</li><li><strong>Lock Page Scroll While Open</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">Phones have no Esc key</p><p>If a panel has no close button and no overlay click, visitors on a phone cannot close it. Add a button inside it that links to <code>#offcanvas-close</code>.</p></div><h3 id="auto-open" tabindex="-1">Auto Open <a class="header-anchor" href="#auto-open" aria-label="Permalink to &quot;Auto Open&quot;">​</a></h3><p><strong>Open By Itself</strong> decides whether the panel opens without a click:</p><ul><li><strong>Never — only from a link</strong></li><li><strong>After the page loads</strong>, after a <strong>Delay</strong> in seconds</li><li><strong>After scrolling down</strong> to a <strong>Scroll Depth</strong> in percent</li><li><strong>When leaving the page (exit intent)</strong></li></ul><p><strong>How Often</strong> sets how often a visitor sees it: <strong>Every page view</strong>, <strong>Once per visit</strong>, or <strong>Once every few days</strong>, with <strong>Show Again After</strong> a number of days.</p><p><strong>On Pages</strong> sets where it opens: the <strong>Entire site</strong>, <strong>Only on…</strong> or <strong>Everywhere except…</strong>. You can pick pages, posts, archives and other targets, as in Layout conditions. You can also type an address such as <code>/blog/*</code>.</p><p><strong>On Devices</strong> turns auto-open on or off for desktop, tablet and mobile.</p>',25)),n("h3",g,[e[3]||(e[3]=t("Schedule ",-1)),a(o,{type:"tip",text:"2.9.3"}),e[4]||(e[4]=t()),e[5]||(e[5]=n("a",{class:"header-anchor",href:"#schedule","aria-label":'Permalink to "Schedule <Badge type="tip" text="2.9.3" />"'},"​",-1))]),e[7]||(e[7]=s("<p><strong>Turn On At</strong> and <strong>Turn Off At</strong> switch the whole panel on and off at a date and time. Times use the site&#39;s timezone (<strong>Settings → General</strong>).</p><ul><li>Leave <strong>Turn On At</strong> empty to start now, and <strong>Turn Off At</strong> empty to never stop.</li><li>Outside these times the panel is off everywhere. Its links do nothing and it never opens by itself, exactly as if its switch in the Library were off.</li><li>Cached pages stop showing the panel on the minute it ends.</li><li>A visitor who has the panel open when it ends sees it close.</li></ul><p>The options show whether the panel is live now, waiting to start, or finished.</p>",3))])}const k=i(d,[["render",c]]);export{y as __pageData,k as default};
